mapper.select:
SELECT *, (ORD_SU - ISNULL(danch_su,0)) AS danch_remain_su, CONCAT(PROD_PG,' ',PROD_PG1,' ~ ') AS prod_pg, CONCAT(PROD_GD3,' ',PROD_GD4,' ~ ',PROD_GD5) AS prod_gd, CONVERT(VARCHAR(10),ord_input,120) AS ord_input_view, CASE WHEN WSTD_T43 IS NULL THEN '0' ELSE WSTD_T43 END AS wstd_t43, ISNULL(product_file_name,'no_image.png') AS product_file_name, ISNULL(wstd_chim_file_name1,'no_image.png') AS wstd_chim_file_name1 FROM ORDERT A LEFT OUTER JOIN ( SELECT ord_code, SUM(ilbo_su) AS danch_su FROM WORKILBO WHERE ilbo_gubn = 'J' GROUP BY ord_code ) B ON A.ord_code = B.ord_code LEFT OUTER JOIN PRODUCT C ON A.prod_code = C.prod_code LEFT OUTER JOIN CORP D ON C.corp_code = D.corp_code LEFT OUTER JOIN ( SELECT PROD_CODE, MAX(REPLACE((CASE WHEN WSTD_T43 IS NULL OR WSTD_T43 = '' THEN '0' ELSE WSTD_T43 END),',','')) AS WSTD_T43, MAX(wstd_t32) AS WSTD_T32, MAX(wstd_t33) AS WSTD_T33, MAX(wstd_t41) AS WSTD_T41, MAX(wstd_t87) AS WSTD_T87, MAX(wstd_t44) AS WSTD_T44, MAX(wstd_t51) AS WSTD_T51, MAX(wstd_t52) AS WSTD_T52, MAX(wstd_t53) AS WSTD_T53, MAX(wstd_t54) AS WSTD_T54, MAX(wstd_t30) AS WSTD_T30, MAX(wstd_chim_file_name1) AS WSTD_CHIM_FILE_NAME1 FROM WORKSTD GROUP BY PROD_CODE ) E ON C.prod_code = E.prod_code WHERE (A.ord_su > B.danch_su OR B.danch_su IS NULL) AND A.ord_input >= '2025-01-01 00:00:00'
AND A.ord_code = #{ord_code}
ORDER BY A.ord_code

SELECT *, (ORD_SU - danch_su) AS danch_remain_su, CONCAT(PROD_PG,' ',PROD_PG1,' ~ ') AS prod_pg, CONCAT(PROD_GD3,' ',PROD_GD4,' ~ ',PROD_GD5) AS prod_gd, CONVERT(VARCHAR(10),ord_input,120) AS ord_input_view, CASE WHEN WSTD_T43 IS NULL THEN '0' ELSE WSTD_T43 END AS wstd_t43 FROM ORDERT A LEFT OUTER JOIN ( SELECT ord_code, SUM(ilbo_su) AS danch_su FROM WORKILBO WHERE ilbo_gubn = 'J' GROUP BY ord_code ) B ON A.ord_code = B.ord_code LEFT OUTER JOIN PRODUCT C ON A.prod_code = C.prod_code LEFT OUTER JOIN CORP D ON C.corp_code = D.corp_code LEFT OUTER JOIN ( SELECT PROD_CODE, MAX(REPLACE((CASE WHEN WSTD_T43 IS NULL OR WSTD_T43 = '' THEN '0' ELSE WSTD_T43 END),',','')) AS WSTD_T43, MAX(wstd_t32) AS WSTD_T32, MAX(wstd_t33) AS WSTD_T33, MAX(wstd_t41) AS WSTD_T41, MAX(wstd_t87) AS WSTD_T87, MAX(wstd_t44) AS WSTD_T44, MAX(wstd_t51) AS WSTD_T51, MAX(wstd_t52) AS WSTD_T52, MAX(wstd_t53) AS WSTD_T53, MAX(wstd_t54) AS WSTD_T54, MAX(wstd_t30) AS WSTD_T30 FROM WORKSTD GROUP BY PROD_CODE ) E ON C.prod_code = E.prod_code WHERE (A.ord_su > B.danch_su OR B.danch_su IS NULL) AND A.ord_input >= '2025-01-01 00:00:00' AND A.prod_code = #{prod_code} AND A.ord_code < #{ord_code}
AND A.ord_code IN
#{ord_code}

SELECT *, CONVERT(VARCHAR(10),ord_input,120) AS ord_input_view, CONCAT(PROD_PG,' ',PROD_PG1,' ~ ') AS prod_pg, CONCAT(PROD_GD3,' ',PROD_GD4,' ~ ',PROD_GD5) AS prod_gd FROM WORKILBO INNER JOIN ORDERT ON WORKILBO.ord_code = ORDERT.ord_code INNER JOIN PRODUCT ON ORDERT.PROD_CODE = PRODUCT.PROD_CODE INNER JOIN CORP ON CORP.CORP_CODE = PRODUCT.CORP_CODE INNER JOIN ( SELECT PROD_CODE, MAX(REPLACE((CASE WHEN WSTD_T43 IS NULL OR WSTD_T43 = '' THEN '0' ELSE WSTD_T43 END),',','')) AS WSTD_T43, MAX(wstd_t32) AS WSTD_T32, MAX(wstd_t33) AS WSTD_T33, MAX(wstd_t41) AS WSTD_T41, MAX(wstd_t87) AS WSTD_T87, MAX(wstd_t44) AS WSTD_T44, MAX(wstd_t51) AS WSTD_T51, MAX(wstd_t52) AS WSTD_T52, MAX(wstd_t53) AS WSTD_T53, MAX(wstd_t54) AS WSTD_T54, MAX(wstd_t30) AS WSTD_T30, MAX(wstd_gj11) AS WSTD_GJ11, MAX(wstd_gj12) AS WSTD_GJ12, MAX(wstd_gj13) AS WSTD_GJ13, MAX(wstd_gj14) AS WSTD_GJ14, MAX(wstd_gj16) AS WSTD_GJ16, MAX(wstd_gj17) AS WSTD_GJ17, MAX(wstd_gj21) AS WSTD_GJ21, MAX(wstd_gj22) AS WSTD_GJ22, MAX(wstd_gj23) AS WSTD_GJ23, MAX(wstd_gj24) AS WSTD_GJ24, MAX(wstd_gj32) AS WSTD_GJ32, MAX(wstd_gj33) AS WSTD_GJ33, MAX(wstd_gj34) AS WSTD_GJ34, MAX(wstd_gj42) AS WSTD_GJ42 FROM WORKSTD GROUP BY PROD_CODE ) WORKSTD ON PRODUCT.PROD_CODE = WORKSTD.PROD_CODE WHERE 1=1
AND ILBO_CODE = #{ilbo_code}
AND ILBO_PC = #{ilbo_code}

SELECT *, CONVERT(VARCHAR(10),ord_input,120) AS ord_input_view, CONCAT(PROD_PG,' ',PROD_PG1,' ~ ') AS prod_pg, CONCAT(PROD_GD3,' ',PROD_GD4,' ~ ',PROD_GD5) AS prod_gd FROM WORKILBO LEFT OUTER JOIN ORDERT ON WORKILBO.ORD_CODE = ORDERT.ORD_CODE LEFT OUTER JOIN PRODUCT ON ORDERT.PROD_CODE = PRODUCT.PROD_CODE LEFT OUTER JOIN CORP ON PRODUCT.CORP_CODE = CORP.CORP_CODE LEFT OUTER JOIN FACILITY ON WORKILBO.FAC_CODE = FACILITY.FAC_CODE INNER JOIN ( SELECT PROD_CODE, MAX(wstd_gj11) AS WSTD_GJ11, MAX(wstd_gj12) AS WSTD_GJ12, MAX(wstd_gj13) AS WSTD_GJ13, MAX(wstd_gj14) AS WSTD_GJ14, MAX(wstd_gj16) AS WSTD_GJ16, MAX(wstd_gj17) AS WSTD_GJ17, MAX(wstd_gj21) AS WSTD_GJ21, MAX(wstd_gj22) AS WSTD_GJ22, MAX(wstd_gj23) AS WSTD_GJ23, MAX(wstd_gj24) AS WSTD_GJ24, MAX(wstd_gj32) AS WSTD_GJ32, MAX(wstd_gj33) AS WSTD_GJ33, MAX(wstd_gj34) AS WSTD_GJ34, MAX(wstd_gj42) AS WSTD_GJ42 FROM WORKSTD GROUP BY PROD_CODE ) WORKSTD ON PRODUCT.PROD_CODE = WORKSTD.PROD_CODE
WHERE 1=1
AND ILBO_CODE = #{ilbo_code}

SELECT * FROM FACILITY WHERE 1=1
AND FAC_GYU = #{fac_gyu}
ORDER BY FAC_NAME
